4032|process_response(struct module_qstate* qstate, struct iter_qstate* iq, 
4033|	struct iter_env* ie, int id, struct outbound_entry* outbound,
4034|	enum module_ev event)
4035|{
4036|	struct msg_parse* prs;
4037|	struct edns_data edns;
4038|	sldns_buffer* pkt;
4039|
4040|	verbose(VERB_ALGO, "process_response: new external response event");
4041|	iq->response = NULL;
4042|	iq->state = QUERY_RESP_STATE;
4043|	if(event == module_event_noreply || event == module_event_error) {
4044|		if(event == module_event_noreply && iq->timeout_count >= 3 &&
4045|			qstate->env->cfg->use_caps_bits_for_id &&
4046|			!iq->caps_fallback && !is_caps_whitelisted(ie, iq)) {
4047|			/* start fallback */
4048|			iq->caps_fallback = 1;
4049|			iq->caps_server = 0;
4050|			iq->caps_reply = NULL;
4051|			iq->caps_response = NULL;
4052|			iq->caps_minimisation_state = DONOT_MINIMISE_STATE;
4053|			iq->state = QUERYTARGETS_STATE;
4054|			iq->num_current_queries--;
4055|			/* need fresh attempts for the 0x20 fallback, if
4056|			 * that was the cause for the failure */
4057|			iter_dec_attempts(iq->dp, 3, ie->outbound_msg_retry);
4058|			verbose(VERB_DETAIL, "Capsforid: timeouts, starting fallback");
4059|			goto handle_it;
4060|		}
4061|		goto handle_it;
4062|	}
4063|	if( (event != module_event_reply && event != module_event_capsfail)
4064|		|| !qstate->reply) {
4065|		log_err("Bad event combined with response");
4066|		outbound_list_remove(&iq->outlist, outbound);
4067|		errinf(qstate, "module iterator received wrong internal event with a response message");
4068|		(void)error_response(qstate, id, LDNS_RCODE_SERVFAIL);
4069|		return;
4070|	}
4071|
4072|	/* parse message */
4073|	fill_fail_addr(iq, &qstate->reply->remote_addr,
4074|		qstate->reply->remote_addrlen);
4075|	prs = (struct msg_parse*)regional_alloc(qstate->env->scratch, 
4076|		sizeof(struct msg_parse));
4077|	if(!prs) {
4078|		log_err("out of memory on incoming message");
4079|		/* like packet got dropped */
4080|		goto handle_it;
4081|	}
4082|	memset(prs, 0, sizeof(*prs));
4083|	memset(&edns, 0, sizeof(edns));
4084|	pkt = qstate->reply->c->buffer;
4085|	sldns_buffer_set_position(pkt, 0);
