4087|		verbose(VERB_ALGO, "parse error on reply packet");
4088|		iq->parse_failures++;
4089|		goto handle_it;
4090|	}
4091|	/* edns is not examined, but removed from message to help cache */
4092|	if(parse_extract_edns_from_response_msg(prs, &edns, qstate->env->scratch) !=
4093|		LDNS_RCODE_NOERROR) {
4094|		iq->parse_failures++;
4095|		goto handle_it;
4096|	}
4097|
4098|	/* Copy the edns options we may got from the back end */
4099|	if(edns.opt_list_in) {
4100|		qstate->edns_opts_back_in = edns_opt_copy_region(edns.opt_list_in,
4101|			qstate->region);
4102|		if(!qstate->edns_opts_back_in) {
4103|			log_err("out of memory on incoming message");
4104|			/* like packet got dropped */
4105|			goto handle_it;
4106|		}
4107|		if(!inplace_cb_edns_back_parsed_call(qstate->env, qstate)) {
4108|			log_err("unable to call edns_back_parsed callback");
4109|			goto handle_it;
4110|		}
4111|	}
4112|
4113|	/* remove CD-bit, we asked for in case we handle validation ourself */
4114|	prs->flags &= ~BIT_CD;
4115|
4116|	/* normalize and sanitize: easy to delete items from linked lists */
4117|	if(!scrub_message(pkt, prs, &iq->qinfo_out, iq->dp->name, 
4118|		qstate->env->scratch, qstate->env, qstate, ie)) {
4119|		/* if 0x20 enabled, start fallback, but we have no message */
4120|		if(event == module_event_capsfail && !iq->caps_fallback) {
4121|			iq->caps_fallback = 1;
4122|			iq->caps_server = 0;
4123|			iq->caps_reply = NULL;
4124|			iq->caps_response = NULL;
4125|			iq->caps_minimisation_state = DONOT_MINIMISE_STATE;
4126|			iq->state = QUERYTARGETS_STATE;
4127|			iq->num_current_queries--;
4128|			verbose(VERB_DETAIL, "Capsforid: scrub failed, starting fallback with no response");
4129|		}
4130|		iq->scrub_failures++;
4131|		goto handle_it;
4132|	}
4133|
4134|	/* allocate response dns_msg in region */
4135|	iq->response = dns_alloc_msg(pkt, prs, qstate->region);
4136|	if(!iq->response)
4137|		goto handle_it;
4138|	log_query_info(VERB_DETAIL, "response for", &qstate->qinfo);
4139|	log_name_addr(VERB_DETAIL, "reply from", iq->dp->name,
4140|		&qstate->reply->remote_addr, qstate->reply->remote_addrlen);
4141|	if(verbosity >= VERB_ALGO)
4142|		log_dns_msg("incoming scrubbed packet:", &iq->response->qinfo, 
4143|			iq->response->rep);
4144|	
4145|	if(event == module_event_capsfail || iq->caps_fallback) {
4146|		if(qstate->env->cfg->qname_minimisation &&
4147|			iq->minimisation_state != DONOT_MINIMISE_STATE) {
4148|			/* Skip QNAME minimisation for next query, since that
4149|			 * one has to match the current query. */
4150|			iq->minimisation_state = SKIP_MINIMISE_STATE;
4151|		}
4152|		/* for fallback we care about main answer, not additionals */
4153|		/* removing that makes comparison more likely to succeed */
4154|		caps_strip_reply(iq->response->rep);
4155|
4156|		if(iq->caps_fallback &&
4157|			iq->caps_minimisation_state != iq->minimisation_state) {
4158|			/* QNAME minimisation state has changed, restart caps
4159|			 * fallback. */
4160|			iq->caps_fallback = 0;
4161|		}
4162|
4163|		if(!iq->caps_fallback) {
4164|			/* start fallback */
4165|			iq->caps_fallback = 1;
4166|			iq->caps_server = 0;
4167|			iq->caps_reply = iq->response->rep;
4168|			iq->caps_response = iq->response;
4169|			iq->caps_minimisation_state = iq->minimisation_state;
4170|			iq->state = QUERYTARGETS_STATE;
4171|			iq->num_current_queries--;
4172|			verbose(VERB_DETAIL, "Capsforid: starting fallback");
4173|			goto handle_it;
4174|		} else {
4175|			/* check if reply is the same, otherwise, fail */
4176|			if(!iq->caps_reply) {
4177|				iq->caps_reply = iq->response->rep;
4178|				iq->caps_response = iq->response;
4179|				iq->caps_server = -1; /*become zero at ++,
4180|				so that we start the full set of trials */
4181|			} else if(caps_failed_rcode(iq->caps_reply) &&
4182|				!caps_failed_rcode(iq->response->rep)) {
4183|				/* prefer to upgrade to non-SERVFAIL */
4184|				iq->caps_reply = iq->response->rep;
4185|				iq->caps_response = iq->response;
4186|			} else if(!caps_failed_rcode(iq->caps_reply) &&
4187|				caps_failed_rcode(iq->response->rep)) {
4188|				/* if we have non-SERVFAIL as answer then 
4189|				 * we can ignore SERVFAILs for the equality
4190|				 * comparison */
4191|				/* no instructions here, skip other else */
4192|			} else if(caps_failed_rcode(iq->caps_reply) &&
4193|				caps_failed_rcode(iq->response->rep)) {
4194|				/* failure is same as other failure in fallbk*/
4195|				/* no instructions here, skip other else */
4196|			} else if(!reply_equal(iq->response->rep, iq->caps_reply,
4197|				qstate->env->scratch)) {
4198|				verbose(VERB_DETAIL, "Capsforid fallback: "
4199|					"getting different replies, failed");
4200|				outbound_list_remove(&iq->outlist, outbound);
4201|				errinf(qstate, "0x20 failed, then got different replies in fallback");
4202|				(void)error_response(qstate, id, 
4203|					LDNS_RCODE_SERVFAIL);
4204|				return;
4205|			}
4206|			/* continue the fallback procedure at next server */
4207|			iq->caps_server++;
4208|			iq->state = QUERYTARGETS_STATE;
4209|			iq->num_current_queries--;
4210|			verbose(VERB_DETAIL, "Capsforid: reply is equal. "
4211|				"go to next fallback");
4212|			goto handle_it;
4213|		}
4214|	}
